from pathlib import Path
import re,html,json,xml.etree.ElementTree as ET
r=Path(__file__).resolve().parents[1]
items=[('a-aroma-handi','01','The Aroma Handi','A rounded handi with a curling aroma plume.','Best fit: warm, inviting and clearly biryani.','Rice details soften below 32 px; simplify for tiny use.'),('b-host','02','The Dum Host','A cheerful host serving a generous pot.','Best fit: hospitality and a friendly personality.','Character detail needs more space; use at 48 px or larger.'),('c-emblem','03','The Dum Seal','A sealed vessel combining the letters D and e.','Best fit: bold avatars, stickers and packaging.','More abstract; the name must accompany it initially.')]
cream='#FFF3DD';red='#A63825';green='#254A39';gold='#ECAA35'
def body(p):
 s=p.read_text(); vb=re.search('viewBox="([^"]+)"',s).group(1).split();return re.sub(r'^.*?<svg[^>]*>','',s,flags=re.S).rsplit('</svg>',1)[0],float(vb[2]),float(vb[3])
def embed(p,x,y,w,h,mono=False,dark=False):
 s,sw,sh=body(p)
 if mono:
  s=s.replace(cream,'NEGATIVE_SPACE')
  for c in [red,gold,green]:
   s=s.replace(c,cream if dark else red)
  s=s.replace('NEGATIVE_SPACE',green if dark else cream)
 scale=min(w/sw,h/sh)
 return f'<g transform="translate({x+(w-sw*scale)/2} {y+(h-sh*scale)/2}) scale({scale})">{s}</g>'
parts=[f'<svg xmlns="http://www.w3.org/2000/svg" width="1800" height="1170" viewBox="0 0 1800 1170"><rect width="1800" height="1170" fill="{cream}"/>']
def text(x,y,s,size=22,color=green,weight='400'):
 return f'<text x="{x}" y="{y}" font-family="Arial, sans-serif" font-size="{size}" font-weight="{weight}" fill="{color}">{html.escape(s)}</text>'
parts += [text(65,58,'DUM E BIRYANI / ODISHA',22,green,'700'),text(65,120,'Warmth. Aroma. A handi full of character.',48,red,'700'),text(65,165,'Three original logo directions • flat colours • inspired by your visual references',24)]
for i,(name,num,title,idea,best,risk) in enumerate(items):
 x=60+i*580
 parts += [f'<rect x="{x}" y="205" width="550" height="800" rx="18" fill="#F9E6C3"/>',text(x+28,251,num+(' / RECOMMENDED' if i==0 else ' / CONCEPT'),18,red,'700'),embed(r/'concepts'/f'{name}-symbol.svg',x+95,280,360,250),embed(r/'concepts'/f'{name}.svg',x+28,525,490,250),text(x+28,794,title,29,red,'700'),text(x+28,834,idea,18),text(x+28,868,best,17)]
 parts += [text(x+28,912,'ONE COLOUR',12,green,'700'),embed(r/'concepts'/f'{name}-symbol.svg',x+29,930,48,48,True),text(x+140,912,'32 PX',12,green,'700'),embed(r/'concepts'/f'{name}-symbol.svg',x+151,945,32,32),text(x+225,912,'16 PX',12,green,'700'),embed(r/'concepts'/f'{name}-symbol.svg',x+240,953,16,16)]
parts += [text(65,1054,'Proposed brand promise: Authentic biryani. A flavour for every craving.',24,green,'700')]
for i,(c,n) in enumerate([(red,'Chilli'),(gold,'Saffron'),(cream,'Rice cream'),(green,'Leaf green')]):
 x=65+i*415;parts += [f'<rect x="{x}" y="1090" width="28" height="28" rx="7" fill="{c}" stroke="#D9C5A6"/>',text(x+42,1112,n+'  '+c,18)]
parts+=['</svg>'];(r/'previews/concepts-board.svg').write_text(''.join(parts))
# Proofs stay in previews; they are tests, not approved deliverable variants.
proof=['<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="460" viewBox="0 0 1200 460">',f'<rect width="1200" height="230" fill="{cream}"/><rect y="230" width="1200" height="230" fill="{green}"/>']
for i,(n,*_) in enumerate(items):
 proof.append(embed(r/'concepts'/f'{n}-symbol.svg',400*i+90,15,220,200,True))
 proof.append(embed(r/'concepts'/f'{n}-symbol.svg',400*i+90,245,220,200,True,True))
proof.append('</svg>');(r/'previews/mono-proof.svg').write_text(''.join(proof))
cards=''.join(f'<article><span>0{i+1}</span><h2>{title}</h2><img src="concepts/{n}.svg" alt="{title} logo concept"><p>{idea}</p><p>{best}</p><p class="note">{risk}</p><a href="concepts/{n}.svg" download>Download concept SVG</a></article>' for i,(n,_,title,idea,best,risk) in enumerate(items))
sources=[('rknall/claude-skills','svg-logo-designer'),('neonwatty/logo-designer-skill','logo-designer'),('kaankiziltug/logo-design-skill','logo-design'),('rampstackco/claude-skills','logo-design'),('luongnv89/skills','logo-designer'),('daffy0208/ai-dev-standards','brand-designer'),('oakoss/agent-skills','brand-designer')]
links=' · '.join(f'<a href="https://www.skills.sh/{repo}/{skill}">{repo}</a>' for repo,skill in sources)
doc=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dum E Biryani — Identity directions</title><style>*{{box-sizing:border-box}}body{{margin:0;background:{cream};color:{green};font-family:Arial,sans-serif;line-height:1.6}}main{{max-width:1500px;margin:auto;padding:45px}}h1{{font-size:clamp(36px,5vw,72px);line-height:1.12;color:{red};max-width:1050px}}.eyebrow{{letter-spacing:3px;font-size:13px;font-weight:bold}}.grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}}article{{padding:28px;background:#F9E6C3;border-radius:16px}}article img{{width:100%;height:300px;object-fit:contain}}h2{{font-family:Georgia,serif;color:{red};line-height:1.2}}a{{color:{red}}}.note{{font-size:13px}}section{{padding:30px 0;border-top:1px solid #DDC8AA;margin-top:35px}}.palette{{display:flex;gap:20px;flex-wrap:wrap}}.swatch{{width:200px;height:70px;border-radius:8px;padding:20px;font-size:13px}}.proof{{width:100%;max-width:1000px}}@media(max-width:900px){{main{{padding:24px}}.grid{{grid-template-columns:1fr}}}}</style><main><div class="eyebrow">DUM E BIRYANI · ODISHA · CONCEPT REVIEW 01</div><h1>Authentic flavour.<br>A warm welcome.</h1><p>Proposed identity for a biryani specialist offering authentic biryani in different flavours and varieties.</p><p><strong>Recommendation: 01 — The Aroma Handi.</strong> A simple cooking vessel, a curling aroma plume and warm expressive lettering connect the name with the experience.</p><div class="grid">{cards}</div><section><h2>Brand definition</h2><p><strong>Positioning:</strong> A welcoming biryani specialist in Odisha, bringing authentic flavour and variety to everyday cravings and shared meals.</p><p><strong>Personality:</strong> Warm, flavourful, confident, generous and contemporary.</p><p><strong>Proposed promise:</strong> “Authentic biryani. A flavour for every craving.”</p><p><strong>Short tagline option:</strong> “Many flavours. One love.”</p><p><strong>Voice:</strong> Simple, inviting and appetite-led. Example: “Find your favourite. Share a handi.” Avoid unsupported recipe, sourcing, heritage or cooking-time claims.</p><p><strong>Audience assumption:</strong> Local biryani lovers, including young adults, families and people ordering meals to share. Audience and sales channels remain unverified.</p><p><strong>Name assumption:</strong> Dum E Biryani is the master brand; Odisha is the location signature. Your brief also says Dum E Odisha, so confirm the intended public-facing name before finalising lettering.</p></section><section><h2>Proposed colour and type direction</h2><div class="palette"><div class="swatch" style="background:{red};color:{cream}">Chilli · {red}</div><div class="swatch" style="background:{gold};color:{green}">Saffron · {gold}</div><div class="swatch" style="background:{cream};border:1px solid #DDC8AA">Rice cream · {cream}</div><div class="swatch" style="background:{green};color:{cream}">Leaf green · {green}</div></div><p>Use cream as the main field, chilli for recognition, saffron as a small accent and green for supporting text. Flat fills throughout.</p><p>Logo studies use outlined Georgia Bold / Bold Italic with Arial Rounded Bold or Arial for descriptors. Font files are not redistributed. The chosen wordmark can receive further optical refinement after selection. Supporting typography direction: a warm display serif with a clear sans-serif for menus.</p></section><section><h2>Reference interpretation</h2><p>Your screenshots suggest expressive wordmarks, compact distinctive symbols and selective illustration. We borrowed those design principles rather than copying their logos. The portrait direction echoes the warmth of illustrative marks; the other two use food and letterform ideas.</p><p>The Instagram URL could not be read through the available web access. No existing colours, menu details, address or claims have been assumed from it.</p></section><section><h2>Scale and one-colour checks</h2><img class="proof" src="previews/mono-proof.png" alt="Three symbol concepts shown in one colour on cream and green backgrounds"><p>These are concept proofs. The host loses costume separation in one colour and needs a simplified cut for tiny applications. The Aroma Handi and Dum Seal preserve their main silhouettes; their smallest decorative details will need refinement before a final icon export. Full names belong on larger layouts, not 16 px favicons.</p></section><section><h2>Next decision</h2><p>Select 01, 02 or 03, or identify parts to combine. Confirm whether the main name should be Dum E Biryani or Dum E Odisha. These are original exploration files, not an approved production kit.</p><p>The linked kaankiziltug skill explicitly requires a concept checkpoint before the full kit: “show the logos before building anything else.” The next round can include refined horizontal and stacked logos, transparent PNGs, monochrome variants, a profile icon and usage guidance.</p></section><details><summary>Skill sources and process</summary><p>{links}</p><p>Applied shared principles: brief first, multiple distinct concepts, SVG geometry, flat fills, outlined lettering, one-colour and size proofs, brand palette and typography. The software-specific sync/default-neon workflow does not match this new food-brand brief; the reference skill's fast track and concept checkpoint guide this round.</p><p>Longlist: aroma handi; dum host; DE seal; rice-grain paisley; serving-hand mark; layered-rice monogram; spice sun; sealed-lid wordmark; shared-handi emblem. Three distinct concepts were selected for clarity, relevance and usefulness across likely applications.</p></details></main></html>'''
(r/'brand-review.html').write_text(doc)
report=[]
for p in (r/'concepts').glob('*.svg'):
 tree=ET.parse(p);text=p.read_text();assert 'viewBox=' in text and '<image' not in text and '<text' not in text and '<linearGradient' not in text
 report.append({'file':p.name,'xml':'valid','outlined':True,'flat_fills':True})
(r/'previews/validation.json').write_text(json.dumps(report,indent=2));print('Created review, overview board, and one-colour proof; SVG checks passed.')
